import { reportError } from "./dom";
import { icon } from "./icons";
import { Component } from "./plugin";
import { activeDoc, ownerDoc } from "./realm";

export interface MenuPositionDef { x: number; y: number; width?: number; overlap?: boolean; left?: boolean }
type MenuCallback = (event: MouseEvent | KeyboardEvent) => unknown;

export class MenuItem {
  readonly dom = document.createElement("button");
  private readonly titleEl = document.createElement("span");
  private readonly iconEl = document.createElement("span");
  private readonly checkEl = document.createElement("span");
  private readonly submenuEl = document.createElement("span");
  private disabled = false;
  private label = false;
  private checked: boolean | null = null;
  private childMenu: Menu | null = null;
  callback: MenuCallback | null = null;

  constructor() {
    this.dom.type = "button";
    this.dom.className = "menu-item";
    this.dom.tabIndex = -1;
    this.titleEl.className = "menu-item-title";
    this.iconEl.className = "menu-item-icon";
    this.checkEl.className = "menu-item-check";
    this.checkEl.setAttribute("aria-hidden", "true");
    this.submenuEl.className = "menu-item-submenu";
    this.submenuEl.setAttribute("aria-hidden", "true");
    this.submenuEl.hidden = true;
    this.dom.append(this.iconEl, this.titleEl, this.checkEl, this.submenuEl);
    this.update();
  }

  setTitle(title: string | DocumentFragment): this {
    if (typeof title === "string") { this.titleEl.textContent = title; }
    else { this.titleEl.replaceChildren(title.cloneNode(true)); }
    this.dom.dataset.menuTitle = this.titleEl.textContent ?? "";
    return this;
  }
  setIcon(name: string | null): this { this.iconEl.replaceChildren(...name ? [icon(name)] : []); return this; }
  setChecked(checked: boolean | null): this { this.checked = checked; this.update(); return this; }
  setDisabled(disabled: boolean): this { this.disabled = disabled; this.update(); return this; }
  setWarning(warning: boolean): this { this.dom.classList.toggle("is-warning", warning); return this; }
  setIsLabel(label: boolean): this { this.label = label; this.update(); return this; }
  setSection(section: string): this { this.dom.dataset.section = section; return this; }
  onClick(callback: MenuCallback): this { this.callback = callback; this.update(); return this; }
  get submenu(): Menu | null { return this.childMenu; }
  setSubmenu(): Menu {
    this.childMenu ??= new Menu();
    this.dom.setAttribute("aria-haspopup", "menu");
    this.dom.setAttribute("aria-expanded", "false");
    this.submenuEl.replaceChildren(icon("chevron-right"));
    this.submenuEl.hidden = false;
    this.update();
    return this.childMenu;
  }

  private update(): void {
    this.dom.disabled = this.disabled || this.label || !this.callback && !this.childMenu;
    this.dom.classList.toggle("is-label", this.label);
    this.dom.classList.toggle("is-disabled", this.dom.disabled && !this.label);
    this.dom.classList.toggle("is-checked", this.checked === true);
    this.checkEl.replaceChildren(...this.checked === true ? [icon("check")] : []);
    this.checkEl.hidden = this.checked !== true;
    this.dom.setAttribute("role", this.label ? "presentation" : this.checked === null ? "menuitem" : "menuitemcheckbox");
    if (this.checked === null) { this.dom.removeAttribute("aria-checked"); }
    else { this.dom.setAttribute("aria-checked", String(this.checked)); }
  }
}

export class MenuSeparator {
  readonly dom = document.createElement("div");
  constructor() {
    this.dom.className = "menu-separator";
    this.dom.setAttribute("role", "separator");
  }
}

export class Menu extends Component {
  private static active: Menu | null = null;
  private static readonly eventMenus = new WeakMap<MouseEvent, Menu>();
  private static readonly pendingMenus = new Set<Menu>();
  readonly dom = document.createElement("div");
  private readonly entries: (MenuItem | MenuSeparator)[] = [];
  private readonly sections: string[] = [];
  private readonly hidden: (() => unknown)[] = [];
  private events: AbortController | null = null;
  private parent: HTMLElement | null = null;
  private focusBefore: HTMLElement | null = null;
  private ownerMenu: Menu | null = null;
  private ownerItem: MenuItem | null = null;
  private childMenu: Menu | null = null;
  private selectedItem: MenuItem | null = null;
  private hover: { win: Window; timer: number; item: MenuItem } | null = null;
  private generation = 0;

  constructor() {
    super();
    this.dom.className = "menu";
    this.dom.tabIndex = -1;
    this.dom.setAttribute("role", "menu");
  }

  static dismiss(): void {
    for (const menu of Menu.pendingMenus) { menu.hide(); }
    Menu.active?.hide();
  }
  static forEvent(event: MouseEvent): Menu {
    const existing = this.eventMenus.get(event);
    if (existing) { return existing; }
    Menu.dismiss();
    const menu = new Menu();
    this.eventMenus.set(event, menu);
    this.pendingMenus.add(menu);
    event.preventDefault();
    const generation = menu.generation;
    queueMicrotask(() => {
      this.pendingMenus.delete(menu);
      if (menu.generation === generation && !menu.events && menu.entries.length) {
        try { menu.showAtMouseEvent(event); } catch (error) { reportError(error); }
      }
    });
    return menu;
  }

  setNoIcon(): this { this.dom.classList.add("mod-no-icon"); return this; }
  addSections(sections: string[]): this {
    if (this.events) { throw new Error("Choose menu sections before showing the menu."); }
    const additions = sections.filter((section, index) => !this.sections.includes(section) && sections.indexOf(section) === index);
    const unspecified = this.sections.indexOf("");
    this.sections.splice(unspecified < 0 ? this.sections.length : unspecified, 0, ...additions);
    return this;
  }
  setUseNativeMenu(native: boolean): this {
    if (native) { throw new Error("Native Electron context menus are not implemented. Use the shared DOM menu instead."); }
    return this;
  }
  setParentElement(parent: HTMLElement): this {
    if (this.events) { throw new Error("Choose the menu parent before showing it."); }
    this.parent = parent;
    return this;
  }
  addItem(callback: (item: MenuItem) => unknown): this {
    if (this.events) { throw new Error("Add menu items before showing the menu."); }
    const item = new MenuItem();
    Promise.resolve(callback(item)).catch(reportError);
    this.entries.push(item);
    return this;
  }
  addSeparator(): this {
    if (this.events) { throw new Error("Add separators before showing the menu."); }
    this.entries.push(new MenuSeparator());
    return this;
  }
  onHide(callback: () => unknown): void { this.hidden.push(callback); }
  onHistoryBack(): void { this.hide(); }
  close(): void { this.hide(); }
  override onunload(): void { this.hide(); }

  showAtMouseEvent(event: MouseEvent): this {
    const target = event.target instanceof Element ? event.target : null;
    const bounds = !event.clientX && !event.clientY ? target?.getBoundingClientRect() : null;
    return this.openAt({ x: bounds?.left ?? event.clientX, y: bounds?.bottom ?? event.clientY }, ownerDoc(event), null, null,
      event.detail === 0 && event.clientX === 0 && event.clientY === 0);
  }

  showAtPosition(position: MenuPositionDef, doc: Document = activeDoc()): this {
    return this.openAt(position, doc);
  }

  private openAt(position: MenuPositionDef, requested: Document, ownerMenu: Menu | null = null, ownerItem: MenuItem | null = null, selectFirst = false): this {
    const doc = this.parent?.ownerDocument ?? requested;
    const win = doc.defaultView;
    if (!win) { throw new Error("The window for this context menu is no longer available."); }
    if (!Number.isFinite(position.x) || !Number.isFinite(position.y) || position.width !== undefined && (!Number.isFinite(position.width) || position.width < 0)) {
      throw new Error("Menu coordinates must be finite viewport positions.");
    }
    if (ownerMenu) { this.hide(); } else { Menu.dismiss(); }
    this.ownerMenu = ownerMenu;
    this.ownerItem = ownerItem;
    const events = new AbortController();
    this.events = events;
    if (!ownerMenu) { Menu.active = this; }
    this.focusBefore = doc.activeElement instanceof HTMLElement ? doc.activeElement : null;
    this.render(events.signal);
    const parent = this.parent ?? ownerMenu?.dom.parentElement ?? this.focusBefore?.closest<HTMLElement>("dialog[open]") ?? doc.body;
    if (!parent.isConnected) { this.hide(); throw new Error("The context menu parent is no longer attached to this page."); }
    Object.assign(this.dom.style, { left: "0px", top: "0px", maxHeight: Math.max(32, win.innerHeight - 16) + "px" });
    parent.append(this.dom);
    const bounds = this.dom.getBoundingClientRect();
    let preferred = position.left ? position.x - bounds.width : position.x + (position.overlap ? 0 : position.width ?? 0);
    if (ownerItem && preferred + bounds.width > win.innerWidth - 8) { preferred = ownerItem.dom.getBoundingClientRect().left - bounds.width; }
    const x = Math.max(8, Math.min(preferred, win.innerWidth - bounds.width - 8));
    const y = Math.max(8, Math.min(position.y, win.innerHeight - bounds.height - 8));
    this.dom.style.left = x - bounds.left + "px";
    this.dom.style.top = y - bounds.top + "px";
    const dismiss = (event: Event): void => { if (!(event.target instanceof Node) || !this.contains(event.target)) { this.hide(); } };
    doc.addEventListener("pointerdown", dismiss, { capture: true, signal: events.signal });
    doc.addEventListener("contextmenu", dismiss, { capture: true, signal: events.signal });
    win.addEventListener("blur", () => this.hide(), { signal: events.signal });
    win.addEventListener("resize", () => this.hide(), { signal: events.signal });
    this.dom.addEventListener("keydown", event => this.onKey(event), { signal: events.signal });
    this.dom.addEventListener("pointerleave", () => this.cancelHover(), { signal: events.signal });
    this.dom.addEventListener("pointerenter", () => {
      if (this.ownerMenu && this.ownerItem) {
        this.ownerMenu.cancelHover();
        const focused = this.dom.ownerDocument.activeElement;
        this.ownerMenu.select(this.ownerItem, !focused || !this.contains(focused));
      }
    }, { signal: events.signal });
    (selectFirst ? this.buttons()[0] ?? this.dom : this.dom).focus();
    return this;
  }

  hide(): this {
    this.generation++;
    this.cancelHover();
    Menu.pendingMenus.delete(this);
    const child = this.childMenu;
    this.childMenu = null;
    child?.hide();
    if (!this.events) { return this; }
    this.events.abort();
    this.events = null;
    this.dom.remove();
    this.select(null, false);
    if (this.ownerMenu?.childMenu === this) { this.ownerMenu.childMenu = null; }
    this.ownerItem?.dom.setAttribute("aria-expanded", "false");
    this.ownerMenu = null;
    this.ownerItem = null;
    if (Menu.active === this) { Menu.active = null; }
    if (this.focusBefore?.isConnected) { this.focusBefore.focus(); }
    for (const callback of this.hidden) {
      try { Promise.resolve(callback()).catch(reportError); } catch (error) { reportError(error); }
    }
    return this;
  }

  private buttons(): HTMLButtonElement[] { return [...this.dom.querySelectorAll<HTMLButtonElement>("button:not(:disabled)")]; }
  private contains(target: Node): boolean { return this.dom.contains(target) || Boolean(this.childMenu?.contains(target)); }
  private rootMenu(): Menu { return this.ownerMenu?.rootMenu() ?? this; }
  private ancestorsEligible(): boolean {
    let menu: Menu = this;
    while (menu.ownerMenu) {
      if (!menu.ownerItem || menu.ownerItem.dom.disabled) { return false; }
      menu = menu.ownerMenu;
    }
    return true;
  }
  private select(item: MenuItem | null, focus: boolean): void {
    this.selectedItem?.dom.classList.remove("selected");
    this.selectedItem = item;
    item?.dom.classList.add("selected");
    if (focus) { item?.dom.focus(); }
  }
  private cancelHover(): void {
    if (this.hover) { this.hover.win.clearTimeout(this.hover.timer); this.hover = null; }
  }
  private hoverItem(item: MenuItem): void {
    if (!this.ancestorsEligible()) { this.rootMenu().hide(); return; }
    if (item.dom.disabled) { return; }
    this.select(item, true);
    if (this.childMenu === item.submenu && item.submenu) { this.cancelHover(); return; }
    if (!item.submenu && !this.childMenu) { this.cancelHover(); return; }
    if (this.hover?.item === item) { return; }
    this.cancelHover();
    const win = this.dom.ownerDocument.defaultView;
    if (!win) { return; }
    const generation = this.generation;
    const timer = win.setTimeout(() => {
      this.hover = null;
      if (!this.events || this.generation !== generation || this.selectedItem !== item || item.dom.disabled) { return; }
      if (item.submenu) { this.openSubmenu(item, false); }
      else {
        this.childMenu?.hide();
        if (this.events) { this.select(item, true); }
      }
    }, 250);
    this.hover = { win, timer, item };
  }
  private openSubmenu(item: MenuItem, focus: boolean): void {
    this.cancelHover();
    if (!this.ancestorsEligible()) { this.rootMenu().hide(); return; }
    const submenu = item.submenu;
    if (!submenu || item.dom.disabled) { return; }
    if (this.childMenu !== submenu || !submenu.events) {
      this.childMenu?.hide();
      const bounds = item.dom.getBoundingClientRect();
      submenu.openAt({ x: bounds.right, y: bounds.top }, this.dom.ownerDocument, this, item);
      this.childMenu = submenu;
      item.dom.setAttribute("aria-expanded", "true");
    }
    if (focus) { (submenu.buttons()[0] ?? submenu.dom).focus(); }
    else { item.dom.focus(); }
  }

  private render(signal: AbortSignal): void {
    this.dom.replaceChildren();
    this.select(null, false);
    const rendered: (MenuItem | MenuSeparator)[] = [];
    const sections = new Map<string, MenuItem[]>();
    const flush = (): void => {
      let first = true;
      const ordered = [...sections].sort(([a], [b]) => {
        const rank = (section: string): number => {
          const index = this.sections.indexOf(section), unspecified = this.sections.indexOf("");
          return index < 0 ? unspecified < 0 ? this.sections.length : unspecified : index;
        };
        return rank(a) - rank(b);
      });
      for (const [, items] of ordered) {
        if (!first) { rendered.push(new MenuSeparator()); }
        first = false;
        for (const item of items) {
          item.dom.addEventListener("pointermove", () => this.hoverItem(item), { signal });
          item.dom.addEventListener("focus", () => this.select(item, false), { signal });
          item.dom.addEventListener("click", event => this.activate(item, event), { signal });
          rendered.push(item);
        }
      }
      sections.clear();
    };
    for (const entry of this.entries) {
      if (entry instanceof MenuSeparator) { flush(); rendered.push(entry); }
      else {
        const section = entry.dom.dataset.section ?? "";
        const items = sections.get(section) ?? [];
        items.push(entry);
        sections.set(section, items);
      }
    }
    flush();
    while (rendered.at(-1) instanceof MenuSeparator) { rendered.pop(); }
    for (const entry of rendered) {
      if (entry instanceof MenuSeparator && (!this.dom.lastElementChild || this.dom.lastElementChild.classList.contains("menu-separator"))) { continue; }
      this.dom.append(entry.dom);
    }
  }

  private activate(item: MenuItem, event: MouseEvent | KeyboardEvent): void {
    if (!this.ancestorsEligible()) { this.rootMenu().hide(); return; }
    if (item.submenu) { this.openSubmenu(item, true); return; }
    const callback = item.callback;
    if (item.dom.disabled || !callback) { return; }
    this.rootMenu().hide();
    Promise.resolve().then(() => callback(event)).catch(reportError);
  }

  private onKey(event: KeyboardEvent): void {
    if (event.defaultPrevented || event.isComposing) { return; }
    this.cancelHover();
    const buttons = this.buttons();
    const index = buttons.findIndex(button => button === this.dom.ownerDocument.activeElement);
    if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      event.stopPropagation();
      const next = event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1 : index < 0 ? event.key === "ArrowDown" ? 0 : buttons.length - 1
        : (index + (event.key === "ArrowDown" ? 1 : -1) + buttons.length) % buttons.length;
      if (this.childMenu && buttons[next] !== this.childMenu.ownerItem?.dom) { this.childMenu.hide(); }
      buttons[next]?.focus();
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      event.stopPropagation();
      const item = this.entries.find(entry => entry instanceof MenuItem && entry.dom === this.dom.ownerDocument.activeElement);
      if (item instanceof MenuItem) { this.activate(item, event); }
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      event.stopPropagation();
      const item = this.entries.find(entry => entry instanceof MenuItem && entry.dom === this.dom.ownerDocument.activeElement);
      if (item instanceof MenuItem) { this.openSubmenu(item, true); }
    } else if (event.key === "ArrowLeft" && this.ownerMenu) {
      event.preventDefault();
      event.stopPropagation();
      this.hide();
    } else if (event.key === "Escape" || event.key === "Tab") {
      event.preventDefault();
      event.stopPropagation();
      if (event.key === "Tab") { this.rootMenu().hide(); } else { this.hide(); }
    } else if (event.ctrlKey || event.metaKey) {
      this.rootMenu().hide();
    } else {
      event.stopPropagation();
    }
  }
}
